import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"handl_plugin_ffi","description":"","frontmatter":{},"headers":[],"relativePath":"api/kit-ffi/handl_plugin_ffi/index.md","filePath":"api/kit-ffi/handl_plugin_ffi/index.md"}`),a={name:`api/kit-ffi/handl_plugin_ffi/index.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="handl-plugin-ffi" tabindex="-1">handl_plugin_ffi <a class="header-anchor" href="#handl-plugin-ffi" aria-label="Permalink to “handl_plugin_ffi”">​</a></h1><p>Generic FFI dispatcher for handl.</p><p>This crate provides [<code>FfiOpFunction</code>], a [<code>handl_platform::Function</code>] implementation that dispatches handl calls to arbitrary C symbols loaded via <code>dlopen</code> / <code>dlsym</code>. It plugs into the existing <a href="./handl_plugin_lib_handl::OpRegistry.html"><code>OpRegistry</code></a> with no engine changes.</p><h2 id="pipeline" tabindex="-1">Pipeline <a class="header-anchor" href="#pipeline" aria-label="Permalink to “Pipeline”">​</a></h2><ol><li><strong>Load</strong> the C library via <code>dlopen</code> (cached by name — opened once, reused for the process lifetime).</li><li><strong>Look up</strong> the symbol via <code>dlsym</code> (cached by library + symbol).</li><li><strong>Marshal</strong> each <code>serde_json::Value</code> argument to a C type per its descriptor string.</li><li><strong>Call</strong> the C symbol via a cranelift-generated call stub (<code>cranelift_shim</code>) — no arity ceiling.</li><li><strong>Unmarshal</strong> the return (C type → <code>serde_json::Value</code>).</li><li><strong>Error clause</strong> — when <code>error_on_lt_zero</code> is set and the integer return is negative, extract <code>errno</code> (via <code>__errno_location()</code> on Linux) and return <code>Err(EvalError::Other(format!(&quot;errno: {errno}&quot;)))</code>.</li></ol><h2 id="marshalling-descriptors" tabindex="-1">Marshalling descriptors <a class="header-anchor" href="#marshalling-descriptors" aria-label="Permalink to “Marshalling descriptors”">​</a></h2><table tabindex="0"><thead><tr><th>Descriptor</th><th>C type</th><th>JSON source</th></tr></thead><tbody><tr><td><code>&quot;i32&quot;</code></td><td><code>int32_t</code> (value)</td><td>number (range-checked)</td></tr><tr><td><code>&quot;i64&quot;</code></td><td><code>int64_t</code> (value)</td><td>number</td></tr><tr><td><code>&quot;f64&quot;</code></td><td><code>double</code> (value)</td><td>number</td></tr><tr><td><code>&quot;cstr&quot;</code></td><td><code>const char *</code></td><td>string (NUL-checked)</td></tr><tr><td><code>&quot;strv&quot;</code></td><td><code>char *const *</code></td><td>list of strings/Bytes (NULL-terminated array)</td></tr><tr><td><code>&quot;ptr&quot;</code></td><td><code>void *</code></td><td>number (address)</td></tr><tr><td><code>&quot;handle&quot;</code></td><td><code>void *</code></td><td><code>{&quot;__resource__&quot;: {&quot;ptr&quot;: N}}</code> (opaque handle, ADR-0083 §2.2)</td></tr><tr><td><code>&quot;void&quot;</code></td><td><code>void</code> (return)</td><td>— (returns null)</td></tr><tr><td><code>&quot;in_buf&quot;</code></td><td><code>const void * + size_t</code></td><td><code>Bytes</code> (<code>{__bytes__:[...]}</code> or <code>[...]</code>)</td></tr><tr><td><code>&quot;cbytes&quot;</code></td><td><code>const void * + size_t</code></td><td><code>Bytes</code> (raw, no NUL termination)</td></tr><tr><td><code>&quot;in_ptr&quot;</code></td><td><code>const void *</code></td><td><code>Bytes</code> (bare pointer, no size arg)</td></tr><tr><td><code>&quot;out_buf:N&quot;</code></td><td><code>void * + size_t</code></td><td>— (allocates N; returns <code>{ ret, buf }</code>)</td></tr></tbody></table><p>Buffer descriptors (<code>in_buf</code> / <code>cbytes</code> / <code>out_buf:N</code>) require the <code>Bytes</code> type (ADR-0078 Phase 2 / ADR-0083 §2.1). Struct descriptors remain deferred.</p><h2 id="modules" tabindex="-1">Modules <a class="header-anchor" href="#modules" aria-label="Permalink to “Modules”">​</a></h2><h3 id="handl-plugin-ffi-1" tabindex="-1"><a href="./handl_plugin_ffi.html"><code>handl_plugin_ffi</code></a> <a class="header-anchor" href="#handl-plugin-ffi-1" aria-label="Permalink to “handl_plugin_ffi”">​</a></h3><p><em>3 modules, 8 statics, 9 functions, 9 structs</em></p><h3 id="ffiopfunction" tabindex="-1"><a href="./FfiOpFunction.html"><code>FfiOpFunction</code></a> <a class="header-anchor" href="#ffiopfunction" aria-label="Permalink to “FfiOpFunction”">​</a></h3><p><em>2 functions</em></p><h3 id="cranelift-shim" tabindex="-1"><a href="./cranelift_shim.html"><code>cranelift_shim</code></a> <a class="header-anchor" href="#cranelift-shim" aria-label="Permalink to “cranelift_shim”">​</a></h3><p><em>1 enum, 1 static, 1 type alias, 2 functions, 2 structs</em></p><h3 id="error" tabindex="-1"><a href="./error.html"><code>error</code></a> <a class="header-anchor" href="#error" aria-label="Permalink to “error”">​</a></h3><p><em>2 functions</em></p><h3 id="marshal" tabindex="-1"><a href="./marshal.html"><code>marshal</code></a> <a class="header-anchor" href="#marshal" aria-label="Permalink to “marshal”">​</a></h3><p><em>1 constant, 1 type alias, 28 functions, 5 enums, 6 structs</em></p>`,19)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};